examples.script:
# One row per deployment ring, as a WSUS or Intune export gives it.
$rings = @'
Ring,Machines,UpToDate
Servers,48,46
Workstations,412,367
Laptops,236,175
'@ | ConvertFrom-Csv | Select-Object Ring, Machines, UpToDate,
    @{ Name = 'Compliant'; Expression = {
        [int] (100 * $_.UpToDate / $_.Machines) } }

$options = New-ImageChartOptions -ProgressMaximum 100 `
    -ShowDataLabels -NoProgressHandles -NoLegend -NoPlotBackground
New-ImageChart {
    foreach ($ring in $rings) {
        New-ImageChartProgress $ring.Ring $ring.Compliant
    }
} -Options $options -FilePath patch-compliance.png `
    -Width 560 -Height 240

$rings | Format-Table -AutoSize

# Share sizes, as a storage report or a Get-ChildItem sum gives.
$shares = @'
Share,Department,SizeGB
\\fs01\eng-builds,Engineering,640
\\fs01\eng-source,Engineering,412
\\fs02\eng-media,Engineering,188
\\fs01\sales,Sales,655
\\fs02\finance,Finance,412
\\fs02\marketing,Marketing,318
\\fs02\hr,HR,96
'@ | ConvertFrom-Csv

$departments = $shares | Group-Object Department | ForEach-Object {
    [pscustomobject]@{
        Department = $_.Name
        Shares     = $_.Count
        SizeGB     = [int] ($_.Group |
            Measure-Object SizeGB -Sum).Sum
    }
} | Sort-Object SizeGB -Descending

New-ImageChart {
    foreach ($d in $departments) {
        New-ImageChartTreemap -Name $d.Department -Value $d.SizeGB
    }
} -Options (New-ImageChartOptions -ShowDataLabels -NoLegend) `
    -FilePath storage-treemap.png -Width 640 -Height 320

$departments | Format-Table -AutoSize

# Who calls whom, from a CMDB export or a config file.
$services = @'
Id,Name,Kind,Tier,Status,Callers,Latency
gateway,API gateway,Gateway,0,Healthy,,
identity,Identity,Service,1,Healthy,gateway,
orders,Orders,Service,1,Warning,gateway,
search,Search,Service,1,Healthy,gateway,
sql,Orders DB,Database,2,Warning,orders,41 ms
events,Events,Queue,2,Healthy,orders search,
'@ | ConvertFrom-Csv

$map = {
    # Tier sets the column; position in the tier sets the row.
    foreach ($tier in $services | Group-Object Tier) {
        $row = 0
        foreach ($s in $tier.Group) {
            $node = @{
                Id = $s.Id; Label = $s.Name; Kind = $s.Kind
                Status = $s.Status; Width = 180; Height = 64
                X = 300 * [int] $tier.Name
                Y = 100 * ($row++ - ($tier.Count - 1) / 2)
            }
            New-ImageTopologyNode @node
        }
    }
    foreach ($s in $services) {
        foreach ($caller in (-split $s.Callers) -ne '') {
            New-ImageTopologyEdge $caller $s.Id $s.Latency `
                -Direction Forward -Status $s.Status
        }
    }
}

$view = @{
    TopologyDefinition   = $map
    Title                = 'Orders platform'
    Subtitle             = 'Database latency above target'
    Layout               = 'Manual'
    Width                = 900
    Height               = 420
    FitContentToViewport = $true
}
New-ImageTopology @view -FilePath service-map.png
New-ImageTopology @view -FilePath service-map.html -InteractiveHtml

$services | Format-Table Name, Kind, Status, Callers -AutoSize

# The shape Get-ADUser -Properties Title, Manager returns.
$users = @'
SamAccountName,Name,Title,Manager,Enabled
avery,Avery Stone,Head of IT,,True
morgan,Morgan Lee,Infrastructure lead,avery,True
sam,Sam Park,Service desk lead,avery,True
alex,Alex Kim,Network engineer,morgan,True
jordan,Jordan Bell,Cloud engineer,morgan,False
casey,Casey Ward,Analyst,sam,True
robin,Robin Shaw,Analyst,sam,True
'@ | ConvertFrom-Csv

$members = {
    foreach ($user in $users) {
        $member = @{
            Id     = $user.SamAccountName
            Name   = $user.Name
            Role   = $user.Title
            Status = if ($user.Enabled -eq 'True') { 'Healthy' }
                     else { 'Warning' }
        }
        if ($user.Manager) { $member.ParentId = $user.Manager }
        New-ImageOrganizationMember @member
    }
}
New-ImageOrganizationChart $members -TeamLabel 'IT department' `
    -Subtitle 'Disabled accounts flagged' -NoTeamNode `
    -FilePath org-chart.png -Width 960 -Height 420

$users | Format-Table Name, Title, Manager, Enabled -AutoSize

$rings = @'
Ring,Compliant,Missing
Servers,96,2
Workstations,89,45
Laptops,74,61
'@ | ConvertFrom-Csv

# SocialPreview is 1200 x 630, the size link previews expect.
New-ImageCanvas -Preset SocialPreview -Title 'Patch compliance' `
    -LayerDefinition {
    $text = @{ X = 72; Width = 1056 }
    New-ImageCanvasText @text -Y 72 -Text 'Patch compliance' `
        -FontSize 58 -Emphasized
    New-ImageCanvasText @text -Y 154 -FontSize 26 `
        -Text 'October cumulative update, three rings'
    $x = 72
    foreach ($ring in $rings) {
        $tile = @{
            X = $x; Y = 260; Width = 336; Height = 176
            Icon = $ring.Ring.Substring(0, 2).ToUpper()
            Label = $ring.Ring; Value = "$($ring.Compliant)%"
            Detail = "$($ring.Missing) machines need updates"
            Progress = $ring.Compliant / 100
            Accent = if ([int] $ring.Compliant -ge 90) { '#37c9b8' }
                     else { '#eeb640' }
        }
        New-ImageCanvasInfoTile @tile
        $x += 360
    }
} -FilePath social-card.png

$rings | Format-Table -AutoSize
